        cast<num_t>((r * q + p) % np) / cast<int>(np);

    // C4[i][j] = ( (i*j) % np ) / np;
    // Mapping: i -> j (second index), j -> i (first index) => C4(first=j, second=i)
    init_C4(i, j) =
        cast<num_t>((j * i) % np) / cast<int>(np);

    // -------- Scheduling for initialization --------
    // Use a reasonable vector width based on the host and the element type.
    Target target = get_host_target();
    const int vec_width = natural_vector_size<num_t>(target);

    // A(p, q, r) is laid out with p as the innermost (stride-1) dimension.
    // Vectorize across p and parallelize across the outermost dimension r
    // to get good spatial locality and multi-core utilization.
    init_A
        .bound(p, 0, np)
        .bound(q, 0, nq)
        .bound(r, 0, nr)
        .reorder(p, q, r)
        .vectorize(p, vec_width)
        .parallel(r);

    // C4(i, j) is (i = innermost, j = outer). Vectorize i, parallelize j.
    init_C4
        .bound(i, 0, np)
        .bound(j, 0, np)
        .reorder(i, j)
        .vectorize(i, vec_width)
        .parallel(j);

    // Realize into the provided buffers.
    init_A.realize(A);
    init_C4.realize(C4);
}

