    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    Func doitgen("doitgen");

    // Pure definition (initialize accumulator)
    doitgen(p, q, r) = cast<num_t>(0);
    // Reduction definition (dot product over s)
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // -------- Scheduling for main kernel --------
    {
        Target target = get_host_target();
        const int vec_width = natural_vector_size<num_t>(target);

        // Layout of A_out / doitgen is (p, q, r) with p contiguous.
        // We keep p as the innermost loop and vectorize across it.
        // We parallelize across r (outermost dimension), which corresponds
        // to the original C loop order over r, q, p, s.
        //
        // Pure stage: loop nest shape we want (outer -> inner):
        //   for r in [0, nr)
        //     for q in [0, nq)
        //       for p in [0, np)   // vectorized
        doitgen
            .bound(p, 0, np)
            .bound(q, 0, nq)
            .bound(r, 0, nr)
            .reorder(p, q, r)         // p innermost, then q, then r
            .vectorize(p, vec_width)  // contiguous vector loads/stores
            .parallel(r);             // distribute work across rows r

        // Update (reduction) stage: we keep the same outer loop order
        // (r, q, p) but reorder p to be innermost and vectorize it as well.
        //
        // The default reduction loop order is roughly:
        //   for r, q, p:
        //     for s:
        //       doitgen(p,q,r) += ...
        //
        // We reorder to:
        //   for r, q:
        //     for s:
        //       for p (vectorized):
        //         doitgen(p,q,r) += ...
