        // For each fixed (p, q, r), contributions are still accumulated
        // in increasing s order, matching the original C semantics; we
        // merely interleave work across different p values.
        doitgen.update()
            .reorder(p, s, q, r)      // p innermost, then s, then q, r
            .vectorize(p, vec_width)
            .parallel(r);
    }

    // Bind JIT and compile after scheduling
    doitgen.compile_jit();

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
