    // Sum over 's' corresponds to the inner-most loop over NP
    RDom s(0, A.dim(0).extent(), "s");  // A.dim(0).extent() == np

    // Main computation:
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    Func doitgen("doitgen");

    doitgen(p, q, r) = cast<num_t>(0);
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // ------------------------ Optimized schedule ------------------------
    //
    // Data layout:
    //   A_param(s, q, r):  s is dimension 0 (contiguous in memory)
    //   C4_param(p, s):    p is dimension 0 (contiguous), s is dim 1
    //   doitgen(p, q, r):  p is dimension 0 (contiguous)
    //
    // Original C loop nest:
    //   for (r)
    //     for (q)
    //       for (p)
    //         for (s)
    //           A[r][q][p] += A[r][q][s] * C4[s][p];
    //
    // We want:
    //   - p as the innermost loop to exploit unit-stride access in both
    //     doitgen and C4_param.
    //   - Parallelism across (r, q) pairs.
    //   - Vectorization across p.
    //
    // Strategy:
    //   * Compute doitgen at root (single-stage pipeline).
    //   * Fuse r and q into a single parallel dimension (rq), so we can
    //     distribute work over many cores even if nr or nq individually
    //     are small.
    //   * Split p into [p_outer, p_inner] and vectorize p_inner.
    //   * Apply an analogous schedule to both the pure definition and
    //     the reduction update definition so they share the same loop
    //     structure. This preserves the reduction semantics while
    //     improving locality and SIMD utilization.

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Schedule for the pure (initialization) definition:
    {
        Var rq("rq"), p_outer("p_outer"), p_inner("p_inner");
        doitgen
            .compute_root()
            // Fuse r and q: outer parallel loop over all (r, q) pairs.
            .fuse(r, q, rq)
            .parallel(rq)
            // Vectorize across contiguous p.
            .split(p, p_outer, p_inner, vec_width)
            .vectorize(p_inner);
    }

    // Schedule for the reduction (update) definition:
    {
        Var rq_u("rq_u"), p_outer_u("p_outer_u"), p_inner_u("p_inner_u");
        doitgen
            .update()
            // Same fusion of (r, q) for the reduction stage.
            .fuse(r, q, rq_u)
            .parallel(rq_u)
            // Same vectorization pattern across p.
            .split(p, p_outer_u, p_inner_u, vec_width)
            .vectorize(p_inner_u);
    }

    // JIT-compile with the chosen target. All scheduling must be
    // complete before this call.
    doitgen.compile_jit(target);

    // --------------------- Timing and realization ----------------------

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int r_idx = 0; r_idx < nr; r_idx++) {
            for (int q_idx = 0; q_idx < nq; q_idx++) {
                for (int p_idx = 0; p_idx < np; p_idx++) {
                    // Mapping back to A[r][q][p] -> A_out(p, q, r)
                    std::cerr << A_out(p_idx, q_idx, r_idx) << '\n';
                }
            }
        }
    }

    // Print kernel execution time in seconds, with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
